  const roleRow = row('roles', { gap: 12, align: 'CENTER' });
  roleRow.appendChild(roleBadge('PASIEN'));
  roleRow.appendChild(roleBadge('PETUGAS'));
  roleRow.appendChild(roleBadge('ADMIN'));
  section('Badge', 'Badge status antrean dan badge peran. Warna tidak pernah dipakai sebagai satu-satunya pembeda — label teks selalu ada.', [badgeRow, roleRow]);

  // forms
  const formRow = row('forms', { gap: 32, align: 'START' });
  formRow.appendChild(inputComponent('Input/Default', 'Email', 'nama@contoh.test'));
  formRow.appendChild(inputComponent('Input/Fokus', 'Kata Sandi', '••••••••', { focus: true }));
  formRow.appendChild(inputComponent('Select', 'Poli', 'Poli Gigi dan Mulut (PGT)', { chevron: true }));
  section('Form', 'Label di atas field, tinggi 40px, border 1px, radius 8px, dan ring fokus teal.', [formRow]);

  // cards
  const cardsRow = row('cards', { gap: 16, align: 'START' });

  const poli = figma.createComponent();
  poli.name = 'Kartu/Poli';
  poli.layoutMode = 'VERTICAL';
  poli.primaryAxisSizingMode = 'AUTO';
  poli.counterAxisSizingMode = 'FIXED';
  poli.resize(320, 10);
  poli.paddingTop = 20; poli.paddingBottom = 20; poli.paddingLeft = 20; poli.paddingRight = 20;
  poli.itemSpacing = 8; poli.fills = [solid(C.kartu)]; poli.strokes = [solid(C.garis)];
  poli.strokeWeight = 1; poli.cornerRadius = 12; poli.effects = SHADOW;
  const poliHead = row('head', { w: 280, gap: 8, align: 'CENTER', justify: 'SPACE_BETWEEN' });
  const code = row('kode', { gap: 0, pad: [2, 7, 2, 7], radius: 6, fill: C.latar, stroke: C.garis, align: 'CENTER' });
  code.appendChild(txt('PGT', 'label', C.lembut));
  poliHead.appendChild(code);
  poliHead.appendChild(statusBadge('Buka'));
  poli.appendChild(poliHead);
  poli.appendChild(txt('Poli Gigi dan Mulut', 'h2', C.teks, { width: 280 }));
  poli.appendChild(txt('Layanan kesehatan gigi dan mulut.', 'small', C.lembut, { width: 280 }));
  poli.appendChild(txt('Sisa kuota hari ini: 29', 'small', C.teks, { width: 280 }));
